(function duoApplication(){
'use strict';
const KEY='duo-gym-local-v1';
const IDS=['ella','el'];
const TITLES=['Adaptación','Técnica','Progresión','Consolidación'];
const GOALS={habito:'Crear el hábito',fuerza:'Ganar fuerza',composicion:'Mejorar composición corporal'};
const MOVES={
 press:{name:'Prensa de piernas',area:'Piernas',range:'8–12',min:8,max:12,tip:'Ajusta el asiento, apoya toda la planta y baja solo hasta donde mantengas la pelvis apoyada. Sube sin bloquear las rodillas.',alt:'Sentarse y levantarse de un banco estable.'},
 chest:{name:'Press de pecho en máquina',area:'Pecho · tríceps',range:'8–12',min:8,max:12,tip:'Manijas a la altura del pecho, espalda apoyada y muñecas rectas. Empuja y vuelve lentamente sin perder el control.',alt:'Flexiones contra una pared o un banco alto.'},
 row:{name:'Remo sentado en polea',area:'Espalda',range:'10–12',min:10,max:12,tip:'Torso estable, hombros lejos de las orejas. Lleva los codos hacia atrás sin balancearte.',alt:'Remo en máquina con apoyo de pecho.'},
 curl:{name:'Curl femoral sentado',area:'Parte posterior de piernas',range:'10–15',min:10,max:15,tip:'Alinea la rodilla con el eje de la máquina. Flexiona y regresa despacio, con la cadera apoyada.',alt:'Puente de glúteos en el suelo, sin dolor.'},
 calf:{name:'Elevación de talones',area:'Pantorrillas',range:'12–15',min:12,max:15,tip:'Sujétate de un apoyo, sube los talones y baja con control. Evita rebotar.',alt:'Hazlo sentado, con ambos pies apoyados.'},
 plank:{name:'Plancha con rodillas apoyadas',area:'Abdomen',range:'15–25 s',min:15,max:25,time:true,tip:'Apoya antebrazos y rodillas, mantén el tronco alineado y respira. Termina antes de perder la postura.',alt:'Plancha de pie con antebrazos en una pared.'},
 squat:{name:'Sentadilla a banco con mancuerna',area:'Piernas · glúteos',range:'8–12',min:8,max:12,tip:'Empieza sin peso. Lleva la cadera al banco sin dejarte caer; levántate empujando el suelo. Añade mancuerna solo con buena técnica.',alt:'Prensa de piernas con recorrido cómodo.'},
 lat:{name:'Jalón al pecho',area:'Espalda · bíceps',range:'10–12',min:10,max:12,tip:'Lleva la barra hacia la parte alta del pecho, nunca detrás del cuello. Mantén el torso estable y evita tirones.',alt:'Jalón en máquina con agarre neutro.'},
 bridge:{name:'Puente de glúteos en el suelo',area:'Glúteos',range:'10–15',min:10,max:15,tip:'Rodillas flexionadas y pies firmes. Eleva la cadera sin arquear la espalda; pausa y baja con control.',alt:'Extensión de cadera de pie con apoyo.'},
 shoulder:{name:'Press de hombros en máquina',area:'Hombros',range:'8–12',min:8,max:12,tip:'Espalda apoyada, agarre cómodo y recorrido sin dolor. Evita elevar los hombros hacia las orejas.',alt:'Elevaciones laterales ligeras en un recorrido cómodo.'},
 triceps:{name:'Extensión de tríceps en polea',area:'Tríceps',range:'10–15',min:10,max:15,tip:'Codos junto al cuerpo. Estira los brazos sin inclinar el torso y vuelve despacio.',alt:'Extensión en máquina guiada.'},
 deadbug:{name:'Dead bug',area:'Control abdominal',range:'6–10/lado',min:6,max:10,side:true,tip:'Boca arriba, mueve lentamente brazo y pierna contrarios sin arquear la zona lumbar. Cuenta las repeticiones por lado.',alt:'Desliza un talón cada vez, con ambos brazos apoyados.'},
 biceps:{name:'Curl de bíceps con mancuernas',area:'Bíceps',range:'10–15',min:10,max:15,tip:'Codos cerca del cuerpo, muñecas estables. Flexiona sin balancear la espalda.',alt:'Curl en máquina o polea ligera.'},
 sideplank:{name:'Plancha lateral con rodilla apoyada',area:'Abdomen lateral',range:'10–20 s/lado',min:10,max:20,time:true,side:true,tip:'Codo debajo del hombro y rodilla inferior apoyada. Eleva la cadera, respira y repite del otro lado.',alt:'Plancha lateral de pie contra una pared.'}
};
const ROUTINES={A:['press','chest','row','curl','calf','plank'],B:['squat','lat','bridge','shoulder','triceps','deadbug'],C:['press','chest','row','curl','biceps','sideplank']};
const MEALS=[
 ['Huevos + arepa + fruta','Pollo, arroz y ensalada','Lentejas con arroz y verduras','Yogur natural alto en proteína + fruta'],
 ['Avena con leche o bebida de soya + yogur','Pescado, papa cocida y ensalada','Fríjoles, arepa y aguacate','Queso fresco o tofu + fruta'],
 ['Arepa con queso + huevos + fruta','Carne magra o soya, arroz y verduras','Ensalada de garbanzos con huevo o tofu','Yogur natural o de soya alto en proteína'],
 ['Avena + yogur + fruta','Pollo o tofu, yuca y ensalada','Lentejas, verduras y una porción de arroz','Leche o bebida de soya + un puñado de nueces'],
 ['Huevos con tomate + pan integral','Pescado o tempeh, arroz y vegetales','Fríjoles con verduras + queso o tofu','Yogur natural + fruta'],
 ['Arepa + huevos o tofu revuelto','Pollo o soya, papa y ensalada','Garbanzos con arroz y verduras','Queso fresco o yogur de soya + fruta'],
 ['Avena con leche + fruta + yogur','Comida en familia: proteína, cereal y verduras','Omelette o tofu, arepa y ensalada','Yogur natural + fruta o frutos secos']
];
const FIELDS={weight:[25,300],waist:[35,220],protein:[0,400],sleep:[0,24],water:[0,10],energy:[1,10],minutes:[0,600]};
function today(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function validDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===v;}
function shift(v,n){return new Date(Date.parse(v+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);}
function diff(a,b){return Math.round((Date.parse(a+'T12:00:00Z')-Date.parse(b+'T12:00:00Z'))/86400000);}
function plan(day){if(day>28)return {day,week:4,type:'review',label:day===29?'Revisión':'Próximo mes'};const n=(day-1)%7;return {day,week:Math.ceil(day/7),type:[0,2,4].includes(n)?'strength':([1,5].includes(n)?'cardio':'rest'),routine:{0:'A',2:'B',4:'C'}[n]||null,label:{0:'Fuerza A',1:'Cardio',2:'Fuerza B',3:'Recuperación',4:'Fuerza C',5:'Cardio',6:'Descanso'}[n]};}
function setsFor(week,index,move){if(move.time||move.side)return 2;if(week===1)return 2;if(week===2)return index<3?3:2;return 3;}
function fresh(){return {v:1,start:today(),active:'ella',profiles:{ella:{name:'Ella',height:null,weight:null,goal:'habito'},el:{name:'Él',height:null,weight:null,goal:'habito'}},logs:{ella:{},el:{}},sessions:{ella:{},el:{}}};}
function numberOrNull(v,min,max){if(v===''||v===null||v===undefined)return null;const n=Number(v);if(!Number.isFinite(n)||n<min||n>max)throw Error('Hay un valor fuera de su rango válido.');return n;}
function proteinRange(p){return p.weight?[Math.round(p.weight*1.6),Math.round(p.weight*2),Math.round(p.weight*1.8)]:null;}
function cleanData(input){
 if(!input||input.v!==1||!validDate(input.start)||!IDS.includes(input.active)||!input.profiles||!input.logs||!input.sessions)throw Error('La copia no tiene el formato de Dúo Gym.');
 const out=fresh();out.start=input.start;out.active=input.active;
 for(const id of IDS){
  const p=input.profiles[id];if(!p||typeof p.name!=='string'||!GOALS[p.goal]||!input.logs[id]||!input.sessions[id])throw Error('Falta un perfil o sus registros.');
  out.profiles[id]={name:p.name.trim().slice(0,30)|| (id==='ella'?'Ella':'Él'),height:numberOrNull(p.height,120,230),weight:numberOrNull(p.weight,25,300),goal:p.goal};
  for(const [date,entry]of Object.entries(input.logs[id])){
   if(!validDate(date)||!entry||typeof entry!=='object')throw Error('Un registro tiene una fecha o contenido incorrecto.');
   const row={};for(const [f,r]of Object.entries(FIELDS))row[f]=numberOrNull(entry[f],...r);
   row.notes=typeof entry.notes==='string'?entry.notes.slice(0,1000):'';out.logs[id][date]=row;
  }
  for(const [date,entry]of Object.entries(input.sessions[id])){
   if(!validDate(date)||!entry||typeof entry!=='object')throw Error('Una sesión tiene un formato incorrecto.');
   const day=diff(date,out.start)+1,pl=plan(day);
   if(day<1||day>28||pl.type!=='strength')throw Error('Una sesión no corresponde al calendario del plan.');
   const row={done:entry.done===true,pain:entry.pain===true,notes:typeof entry.notes==='string'?entry.notes.slice(0,1000):'',exercises:{}};
   for(const [key,item] of Object.entries(entry.exercises||{})){
    if(!ROUTINES[pl.routine].includes(key)||!item||typeof item!=='object')throw Error('Una sesión contiene un ejercicio desconocido.');
    const s=numberOrNull(item.sets,0,10),reps=numberOrNull(item.reps,1,180),load=numberOrNull(item.load,0,500);
    if(s!==null&&!Number.isInteger(s))throw Error('Las series deben ser números enteros.');
    if(s&&reps===null)throw Error('Faltan repeticiones en una serie registrada.');
    row.exercises[key]={sets:s||0,reps,load};
   }
   if(row.done&&!Object.values(row.exercises).some(x=>x.sets>0&&x.reps>0))throw Error('Una sesión completada debe incluir algún ejercicio realizado.');
   out.sessions[id][date]=row;
  }
 }
 return out;
}
function seedFromHash(data,hash){
 if(!hash.startsWith('#inicio='))return false;
 const vals=hash.slice(8).split(',').map(Number);
 if(vals.length!==4||vals.some(x=>!Number.isFinite(x)))return false;
 const entries=[[IDS[0],vals[0],vals[1]],[IDS[1],vals[2],vals[3]]];
 if(entries.some(([,h,w])=>h<120||h>230||w<25||w>300))return false;
 for(const [id,h,w]of entries){if(data.profiles[id].height===null)data.profiles[id].height=h;if(data.profiles[id].weight===null)data.profiles[id].weight=w;}
 return true;
}
function entriesInRange(data,id,end){return Object.entries(data.logs[id]).filter(([d])=>d>=data.start&&d<=end).sort(([a],[b])=>a.localeCompare(b));}
function completed(data,id,end){return Object.entries(data.sessions[id]).filter(([d,s])=>d>=data.start&&d<=end&&s.done).length;}
function due(data,end,includeToday=true){let n=0;for(let d=1;d<=28;d++){const date=shift(data.start,d-1);if(plan(d).type==='strength'&&(includeToday?date<=end:date<end))n++;}return n;}
function average(rows,key){const vals=rows.map(([,v])=>v[key]).filter(v=>typeof v==='number');return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;}
function weights(data,id,end){const pts=entriesInRange(data,id,end).filter(([,r])=>r.weight!==null).map(([d,r])=>({d,v:r.weight}));const p=data.profiles[id];if(p.weight&&data.start<=end&&!pts.some(x=>x.d===data.start))pts.unshift({d:data.start,v:p.weight});return pts;}
function suggestions(data,id,end){
 const recent=entriesInRange(data,id,end).filter(([d])=>diff(end,d)<=6),tips=[];
 const painful=Object.entries(data.sessions[id]).some(([d,s])=>d<=end&&diff(end,d)<=6&&s.pain);
 if(painful)tips.push({warn:true,text:'Registraste dolor al entrenar. Detén los movimientos que lo provocan y revisa la técnica con el instructor; si persiste, busca valoración.'});
 const count=k=>recent.filter(([,v])=>typeof v[k]==='number').length;
 if(count('sleep')>=3&&average(recent,'sleep')<7)tips.push({text:'En tus registros recientes el sueño promedia menos de 7 horas. Prioriza una hora regular para dormir y ajusta la carga si estás fatigado.'});
 const range=proteinRange(data.profiles[id]);
 if(range&&count('protein')>=3&&average(recent,'protein')<range[0])tips.push({text:'Tu proteína registrada queda por debajo del rango orientativo. Revisa que estés anotando todo e incluye una fuente de proteína en cada comida.'});
 if(count('energy')>=3&&average(recent,'energy')<=4)tips.push({text:'Has registrado energía baja varios días. Revisa descanso y alimentación; conserva una carga cómoda y pide valoración si el cansancio persiste.'});
 const pastDue=due(data,end,false),pastDone=Object.entries(data.sessions[id]).filter(([d,s])=>d<end&&s.done).length;
 if(pastDue>=3&&pastDone<pastDue*.67)tips.push({text:'Hay sesiones anteriores sin completar en el registro. Actualiza lo que sí hiciste y retoma el calendario; evita juntar sesiones para compensar.'});
 if(!tips.length)tips.push({text:recent.length<3?'Registra al menos tres días para recibir observaciones sobre tus hábitos. El objetivo de esta semana es aprender los movimientos y ser constante.':'Sigue registrando cómo te sientes. Aumenta la dificultad solo cuando completes el rango con buena técnica y te queden unas dos repeticiones posibles.'});
 return tips.slice(0,3);
}
function progressionHint(data,id,move,date){
 const pl=plan(diff(date,data.start)+1);
 const last=Object.entries(data.sessions[id]).filter(([d,s])=>d<date&&s.done&&s.exercises[move]?.sets>0).sort(([a],[b])=>b.localeCompare(a)).slice(0,2);
 if(last.length<2)return 'Usa una carga que permita todas las repeticiones con control. Anota tus resultados para comparar próximas sesiones.';
 if(last.some(([,s])=>s.pain))return 'Hay dolor registrado en una sesión previa. Revisa el ejercicio antes de aumentar la dificultad.';
 const m=MOVES[move];
 const ready=last.every(([d,s])=>{
  const prev=plan(diff(d,data.start)+1),index=ROUTINES[prev.routine].indexOf(move),x=s.exercises[move];
  return x.reps>=m.max&&x.sets>=setsFor(prev.week,index,m);
 });
 if(!ready)return 'Conserva una dificultad cómoda hasta completar todas las series en el extremo alto del rango.';
 return m.time||m.side?'Alcanzaste el extremo alto en dos sesiones. Mantén buena postura antes de aumentar el tiempo o la dificultad.':'Alcanzaste el extremo alto en dos sesiones. Si la técnica fue buena y aún podías hacer 2 repeticiones más, prueba el menor aumento disponible (aprox. 2–5 %).';
}
const Core={KEY,IDS,MOVES,ROUTINES,plan,setsFor,fresh,validDate,shift,diff,numberOrNull,proteinRange,cleanData,seedFromHash,completed,due,average,weights,suggestions,progressionHint};
if(typeof document==='undefined'){globalThis.DuoCore=Core;return;}
let data=fresh(),storageWarning='',storedRaw=null;
try{storedRaw=localStorage.getItem(KEY);if(storedRaw)data=cleanData(JSON.parse(storedRaw));}catch(e){storageWarning='No se pudo leer el guardado. No se reemplazará automáticamente. Revisa Ajustes para recuperar una copia o comenzar de nuevo.';}
let storageBlocked=!!storageWarning;
if(seedFromHash(data,location.hash)){if(!storageBlocked){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{storageWarning='El navegador no permite guardar. Exporta una copia antes de cerrar.';storageBlocked=true;}}}
if(location.hash.startsWith('#inicio='))history.replaceState(null,'',location.pathname+location.search);
let view='home',selectedDay=Math.min(30,Math.max(1,diff(today(),data.start)+1)),menuDay=0,dirty=false,toastTimer,installEvent=null;
const root=document.getElementById('app');
const iconPaths={home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-7h6v7',dumbbell:'M6 7v10M3 9v6M18 7v10M21 9v6M6 12h12',food:'M5 3v7c0 3 5 3 5 0V3M7.5 3v18M17 3c-3 4-3 8 1 9V3M18 12v9',chart:'M4 3v17h17M8 15l4-5 4 2 5-7',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',check:'M5 12l4 4L19 6',leaf:'M19 4C7 3 3 8 6 16c7 5 15 0 13-12ZM6 17l9-9',water:'M12 3c-3 5-7 8-7 12a7 7 0 0 0 14 0c0-4-4-7-7-12Z',moon:'M20 15A8 8 0 0 1 9 4 9 9 0 1 0 20 15Z',arrow:'M4 12h16M14 6l6 6-6 6',save:'M5 3h12l4 4v14H3V3h2ZM7 3v6h10V3M7 21v-8h10v8',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',plus:'M12 5v14M5 12h14',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-2a6 6 0 0 1 12 0v2M16 5a4 4 0 0 1 0 8M17 16a5 5 0 0 1 5 5',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4z',heart:'M12 21S2 14 2 8c0-6 7-7 10-2 3-5 10-4 10 2 0 6-10 13-10 13Z'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.leaf}"/></svg>`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function prettyDate(v,opts={day:'numeric',month:'short'}){return new Date(v+'T12:00:00').toLocaleDateString('es-CO',opts);}
function fmt(v,d=1){return v===null||v===undefined?'—':Number(v).toLocaleString('es-CO',{maximumFractionDigits:d});}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function persist(next,message){
 if(storageBlocked){toast('El guardado está bloqueado para proteger la copia anterior. Revisa Ajustes.');return false;}
 try{localStorage.setItem(KEY,JSON.stringify(next));data=next;dirty=false;storageWarning='';if(message)toast(message);return true;}
 catch{toast('Los cambios quedan solo en esta pestaña. Exporta una copia desde Ajustes antes de cerrar.');storageWarning='El navegador no permite guardar de forma permanente. Los cambios están solo en memoria: exporta una copia antes de cerrar.';data=next;dirty=false;render();return false;}
}
function clone(){return JSON.parse(JSON.stringify(data));}
function abandon(){return !dirty||confirm('Hay cambios sin guardar. ¿Quieres salir sin guardarlos?');}
function navButton(id,label,ico){return `<button type="button" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`;}
function header(title,description){return `<div class="page-title"><div class="eyebrow">TU MES DE MOVIMIENTO</div><h1>${title}</h1><p class="muted">${description}</p></div>`;}
function stat(label,value,sub,ico){return `<div class="card stat"><div><span class="small">${label}</span><strong>${value}</strong><div class="small">${sub}</div></div><div class="iconbox">${icon(ico)}</div></div>`;}
function hints(){return suggestions(data,data.active,today()).map(t=>`<div class="hint ${t.warn?'warning':''}">${t.text}</div>`).join('');}
function profileSummary(id){const p=data.profiles[id];return `${p.height?fmt(p.height,0)+' cm':'Estatura pendiente'} · ${p.weight?fmt(p.weight)+' kg iniciales':'Peso inicial pendiente'}`;}
function render(){
 const p=data.profiles[data.active];
 root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">dúo<em>.</em></div><div class="tagline">Tu mes de movimiento</div><nav class="nav" aria-label="Navegación principal">${navButton('home','Mi día','home')}${navButton('workout','Rutina','dumbbell')}${navButton('nutrition','Nutrición','food')}${navButton('progress','Progreso','chart')}${navButton('settings','Ajustes','settings')}</nav><div class="side-foot">${icon('leaf')}<b>Un paso a la vez.</b>Más fuerza, mejores hábitos y un progreso propio.</div></aside><div class="workspace"><header class="topbar"><div class="top-title">Cada persona, su propio progreso.</div><div class="brand mobile-brand">dúo<em>.</em></div><div class="profile-switch" role="group" aria-label="Seleccionar perfil">${IDS.map(id=>`<button type="button" data-profile="${id}" class="${id===data.active?'active':''}" aria-pressed="${id===data.active}"><span class="avatar ${id}">${esc(data.profiles[id].name.slice(0,1).toUpperCase())}</span><span>${esc(data.profiles[id].name)}</span></button>`).join('')}</div></header><main id="main" tabindex="-1">${storageWarning?`<div class="notice">${esc(storageWarning)}</div>`:''}${p.weight&&p.height?'':`<div class="notice">Completa las medidas de ${esc(p.name)} para mostrar su orientación de proteína. <button class="btn flat" data-view="settings">Completar perfil ${icon('arrow')}</button></div>`}${({home:homeView,workout:workoutView,nutrition:nutritionView,progress:progressView,settings:settingsView}[view])()}</main></div></div><dialog id="daily-dialog" class="dialog-box"></dialog>`;
 if(view==='settings')bindImport();
}
function homeView(){
 const p=data.profiles[data.active],day=Math.min(30,Math.max(1,diff(today(),data.start)+1)),pl=plan(day),count=completed(data,data.active,today()),range=proteinRange(p),rows=entriesInRange(data,data.active,today()),last=weights(data,data.active,today()).at(-1),running=diff(today(),data.start);
 const status=running<0?'Comienzas el '+prettyDate(data.start):running>=30?'Mes completado':'Día '+day+' de 30';
 return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${status} · ${esc(p.name)}</div><h1>Pequeños pasos.<br><em>Cambios que se quedan.</em></h1><p>Tu primer mes para crear hábitos, ganar fuerza y descubrir lo que puedes hacer.</p><button class="btn lime" data-action="today">Ver mi entrenamiento ${icon('arrow')}</button></div><svg class="hero-art" viewBox="0 0 280 280" aria-hidden="true"><circle cx="160" cy="150" r="100" fill="none" stroke="currentColor" stroke-width="1"/><circle cx="160" cy="150" r="75" fill="none" stroke="currentColor" stroke-width="1"/><path d="M75 200L205 70M67 170l45 45M51 185l46 46M170 68l45 45M185 52l46 46" fill="none" stroke="currentColor" stroke-width="16" stroke-linecap="round"/></svg></section><div class="stack"><div class="grid3 stats">${stat('Sesiones de fuerza',count+' <span>/ 12 del plan</span>',due(data,today())+' previstas hasta hoy','dumbbell')}${stat('Peso registrado',last?fmt(last.v)+' <span>kg</span>':'— <span>sin registro</span>',last?prettyDate(last.d):'Añade tu punto de partida','chart')}${stat('Proteína diaria',range?range[0]+'–'+range[1]+' <span>g orientativos</span>':'— <span>completa el perfil</span>','Rango para adultos sanos','food')}</div><div class="grid2"><section class="card"><div class="section-head"><h2>Tu siguiente paso</h2><span class="pill">${pl.type==='strength'?'FUERZA':'RECUPERACIÓN'}</span></div><div class="eyebrow">SEMANA ${pl.week} · ${TITLES[pl.week-1]}</div><h3 class="session-name">${pl.label}</h3><p class="muted">${pl.type==='strength'?'Un entrenamiento de todo el cuerpo con cargas elegidas por ti. Reserva unos 45–60 minutos.':pl.type==='cardio'?'Camina o pedalea a un ritmo que te permita conversar. Empieza con una duración que puedas mantener.':'Recuperar también forma parte del plan. Muévete con suavidad y revisa cómo te sientes.'}</p><div class="list">${(pl.type==='strength'?ROUTINES[pl.routine].slice(0,3):['Caminar sin prisa','Movilidad cómoda','Preparar tu próxima sesión']).map((e,i)=>`<div class="list-row"><span class="number">${String(i+1).padStart(2,'0')}</span><span>${pl.type==='strength'?MOVES[e].name:e}</span></div>`).join('')}</div><div class="form-actions"><button class="btn primary" data-action="today">Abrir rutina ${icon('arrow')}</button></div></section><section class="card"><div class="section-head"><h2>En qué puedes mejorar</h2>${icon('leaf')}</div>${hints()}<hr class="subtle-divider"><div class="row between wrap"><div><b>¿Cómo estuvo tu día?</b><p class="small">Sueño, alimentación y cómo te sientes.</p></div><button class="btn" data-action="daily">${icon('plus')} Registrar</button></div></section></div><section class="card"><div class="section-head"><div><h2>Un mes, cuatro pasos</h2><p class="small">La constancia es la medida principal de este comienzo.</p></div><span class="pill">${Math.round(count/12*100)} % registrado</span></div><div class="progress"><progress max="12" value="${count}" aria-label="Sesiones completadas">${count} de 12</progress></div><div class="week-strip">${TITLES.map((t,i)=>`<div class="week-piece ${pl.week===i+1?'current':''}"><b>0${i+1} · ${t}</b>${['Conoce los movimientos','Repite con control','Avanza si estás listo','Consolida y revisa'][i]}</div>`).join('')}</div></section><p class="small">Ambos pueden compartir los ejercicios de base. Cada perfil conserva sus propias cargas, registros y observaciones. Un mes permite construir hábitos; los cambios físicos varían entre personas.</p></div>`;
}
function workoutView(){
 const pl=plan(selectedDay),date=shift(data.start,selectedDay-1),s=data.sessions[data.active][date]||{exercises:{}},future=date>today();
 return header('Tu rutina, a tu ritmo.','Plan inicial de 30 días · 3 sesiones de fuerza por semana · '+esc(data.profiles[data.active].name))+`<div class="stack"><section class="card"><div class="section-head"><div><h2>Calendario del mes</h2><p class="small">${prettyDate(data.start)} — ${prettyDate(shift(data.start,29))}</p></div><button class="btn flat" data-action="today">Hoy</button></div><div class="calendar">${Array.from({length:30},(_,i)=>{const p=plan(i+1),d=shift(data.start,i),done=data.sessions[data.active][d]?.done;return `<button data-day="${i+1}" class="${i+1===selectedDay?'selected ':''}${done?'done ':''}${d>today()?'future':''}" aria-pressed="${i+1===selectedDay}" aria-label="Día ${i+1}, ${p.label}, ${prettyDate(d)}${done?', completado':''}"><b>${done?'✓ ':''}${i+1}</b><small>${p.type==='strength'?'Fuerza '+p.routine:p.type==='rest'?'Descanso':p.type==='review'?'Revisión':'Cardio'}</small></button>`;}).join('')}</div><p class="small">Toca un día para consultar la sesión. Las marcas ✓ son entrenamientos que registraste.</p></section><section class="card"><div class="section-head"><div><div class="eyebrow">DÍA ${selectedDay} · ${prettyDate(date)} · SEMANA ${pl.week}</div><h2 class="session-name">${pl.label}</h2></div><span class="pill">${TITLES[pl.week-1]}</span></div>${pl.type==='strength'?`<div class="inset"><b>Antes de empezar</b><p class="small">5–8 min de caminata o bici suave y 1 serie ligera de preparación en los primeros movimientos. Descansa 90–120 s entre series principales y 60–90 s en brazos y abdomen. Semana 1: termina pudiendo hacer 3–4 repeticiones más; después, unas 2–3.</p></div><p class="small">Pide al instructor que ajuste las máquinas y revise tu técnica. No pruebes pesos máximos. Detén cualquier ejercicio con dolor agudo; ante dolor de pecho, desmayo o falta de aire inusual, suspende y busca atención.</p><form id="session-form" data-date="${date}">${ROUTINES[pl.routine].map((id,i)=>{const m=MOVES[id],r=s.exercises[id]||{},target=setsFor(pl.week,i,m);return `<article class="exercise"><div class="row between"><div><span class="small">${String(i+1).padStart(2,'0')} · ${m.area}</span><h3>${m.name}</h3></div><span class="pill">${target} × ${m.range}</span></div><details class="details"><summary>Técnica y alternativa</summary><p class="small">${m.tip}</p><p class="small"><b>Alternativa:</b> ${m.alt} Úsala con una dificultad equivalente y anótalo en tus notas.</p></details><div class="exercise-grid"><label>Carga usada · kg<input type="number" inputmode="decimal" min="0" max="500" step="0.5" name="${id}-load" value="${r.load??''}" placeholder="0 = sin carga"></label><label>${m.time?'Segundos':m.side?'Reps por lado':'Reps por serie'}<input type="number" inputmode="numeric" min="1" max="180" step="1" name="${id}-reps" value="${r.reps??''}" placeholder="${m.min}–${m.max}"></label><label>Series hechas<input type="number" inputmode="numeric" min="0" max="10" step="1" name="${id}-sets" value="${r.sets??''}" placeholder="De ${target} previstas"></label></div><p class="small">${progressionHint(data,data.active,id,date)}</p></article>`;}).join('')}<p class="small">Anota las repeticiones que lograste en todas las series; si variaron, usa la menor y explica el detalle en las notas. En planchas por lado, registra el tiempo de cada lado.</p><label class="check"><input type="checkbox" name="done" ${s.done?'checked':''}>Completé esta sesión (incluidas las adaptaciones necesarias)</label><label class="check"><input type="checkbox" name="pain" ${s.pain?'checked':''}>Sentí dolor durante algún movimiento</label><label class="full">Notas de la sesión<textarea name="notes" maxlength="1000" placeholder="Ejercicio adaptado, repeticiones por serie, sensaciones…">${esc(s.notes||'')}</textarea></label><div class="form-actions"><span class="small">${future?'Podrás registrar esta sesión cuando llegue la fecha.':'Solo se guarda en este navegador.'}</span><button class="btn primary" type="submit" ${future?'disabled':''}>${icon('save')} Guardar sesión</button></div></form>`:pl.type==='cardio'?`<div class="inset"><h3>${[15,20,25,30][pl.week-1]} minutos como referencia</h3><p>Camina o usa la bicicleta a un ritmo que te permita hablar en frases. Puedes dividirlo en bloques más cortos o mantener el tiempo de la semana anterior si aún lo necesitas.</p></div><div class="list"><div class="list-row">${icon('clock')}<p>Comienza y termina suavemente. Añade caminatas cotidianas de forma gradual.</p></div><div class="list-row">${icon('heart')}<p>El objetivo general a largo plazo es llegar a 150 min semanales de actividad moderada, según tolerancia. Este mes es una adaptación.</p></div></div><div class="form-actions"><button class="btn primary" data-action="daily" data-date="${date}" ${future?'disabled':''}>Registrar actividad</button></div>`:pl.type==='review'?`<div class="inset"><h3>Reconoce lo que construiste</h3><p>Revisa cuántas sesiones registraste, tu técnica, las cargas y cómo te sientes. El peso puede cambiar por agua y otros factores; no mide por sí solo la ganancia muscular.</p></div><div class="list"><div class="list-row"><span class="number">1</span><p>Elige un hábito que quieras mantener el próximo mes.</p></div><div class="list-row"><span class="number">2</span><p>Repite una semana cómoda o pide al instructor un ajuste según tus registros.</p></div><div class="list-row"><span class="number">3</span><p>Exporta una copia antes de comenzar un plan nuevo desde Ajustes.</p></div></div><div class="form-actions"><button class="btn primary" data-view="progress">Ver mi progreso ${icon('arrow')}</button></div>`:`<div class="inset"><h3>Hoy toca recuperar</h3><p>Descansa o camina suavemente 10–20 minutos si te apetece. Haz movilidad cómoda de hombros, caderas y tobillos durante unos minutos, sin forzar.</p></div><p class="muted">Procura un horario de sueño regular y come con normalidad. Una sesión difícil no se compensa dejando de comer.</p><div class="form-actions"><button class="btn primary" data-action="daily" data-date="${date}" ${future?'disabled':''}>Registrar cómo me siento</button></div>`}</section><div class="hint">Esta base es para adultos que empiezan y pueden hacer ejercicio sin restricciones. Si hay lesiones, embarazo, una condición médica o experiencia previa diferente, el plan necesita adaptación individual. La talla y el peso no bastan para elegir tus cargas.</div><a class="small" href="https://www.cdc.gov/physical-activity-basics/adding-adults/what-counts.html" target="_blank" rel="noopener noreferrer">Referencia general: actividad física para adultos · CDC</a></div>`;
}
function nutritionView(){
 const p=data.profiles[data.active],range=proteinRange(p),meals=MEALS[menuDay],logged=data.logs[data.active][today()]?.protein;
 return header('Comer bien también cuenta.','Una orientación propia para '+esc(p.name)+'. Las porciones se ajustan a tu hambre, actividad y evolución.')+`<div class="stack"><div class="grid2"><section class="card nutrition-target"><span class="eyebrow">TU REFERENCIA DE PROTEÍNA</span><div class="macro">${range?range[0]+'–'+range[1]:'—'} <span>g al día</span></div><p>${range?'Orientación de 1,6–2,0 g/kg para un adulto sano que entrena fuerza, usando tu peso inicial de '+fmt(p.weight)+' kg.':'Completa tu peso inicial en Ajustes para calcular el rango orientativo.'}</p><hr class="subtle-divider"><div class="row between wrap"><div><b>${logged===undefined||logged===null?'Aún sin registro hoy':fmt(logged)+' g registrados hoy'}</b><p class="small">Puedes repartirla en 3–4 comidas.</p></div><button class="btn" data-action="daily">${icon('plus')} Registrar</button></div></section><section class="card"><h2>Una base sencilla</h2><div class="list"><div class="list-row">${icon('food')}<p>Incluye una fuente de proteína, verduras o fruta, y arroz, papa, avena, arepa u otro cereal según tu apetito.</p></div><div class="list-row">${icon('water')}<p>Bebe agua con las comidas y al entrenar; ajusta por sed, calor y sudor. Sigue cualquier indicación médica sobre líquidos.</p></div><div class="list-row">${icon('moon')}<p>Para la mayoría de adultos, apunta a 7–9 horas de sueño y un horario constante.</p></div></div></section></div><section class="card"><div class="section-head"><div><h2>Tu semana de comidas</h2><p class="small">7 ideas para repetir y variar durante las 4 semanas.</p></div><span class="pill">EJEMPLOS FLEXIBLES</span></div><div class="week-tabs" role="group" aria-label="Día del menú">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map((d,i)=>`<button data-menu="${i}" class="${i===menuDay?'active':''}" aria-pressed="${i===menuDay}">${d}</button>`).join('')}</div>${meals.map((m,i)=>`<div class="meal"><span class="number">${['01','02','03','04'][i]}</span><div><h3>${['Desayuno','Almuerzo','Cena','Merienda opcional'][i]}</h3><p>${m}</p></div></div>`).join('')}<hr class="subtle-divider"><h3>Cómo ajustar tu porción</h3><p class="small">${range?'Si haces 4 comidas con proteína, una referencia inicial es alrededor de '+Math.round(range[0]/4)+'–'+Math.round(range[1]/4)+' g de proteína en cada una.':'Usa una fuente de proteína en tus comidas y completa tu perfil para ver una referencia en gramos.'} Son gramos de proteína, no el peso del alimento. Consulta etiquetas y adapta las cantidades; estas ideas no garantizan por sí solas cubrir tus necesidades.</p><p class="small">Por ejemplo: 100 g de pollo cocido aportan aproximadamente 30 g de proteína; 2 huevos, unos 12 g; una taza de lentejas cocidas, unos 18 g. Los valores cambian con el alimento y la preparación. Si eliges alternativas vegetales, ajusta la cantidad: no siempre son equivalentes por porción.</p></section><div class="grid2"><section class="card"><h2>Tu objetivo: ${GOALS[p.goal].toLowerCase()}</h2><p class="muted">${p.goal==='fuerza'?'Come suficiente para rendir y recuperarte. Si la energía cae o pierdes peso sin buscarlo, revisa tus porciones y tu descanso.':p.goal==='composicion'?'Prioriza fuerza, proteína y hábitos consistentes. Observa energía, cintura y rendimiento durante varias semanas antes de ajustar la comida.':'Empieza por horarios realistas y comidas que puedas repetir. Cambia un hábito a la vez y observa cómo te sientes.'}</p><p class="small">Sin edad, actividad cotidiana, historial y objetivo concreto no sería fiable fijar calorías o una meta de peso. Este menú es una guía, no una dieta clínica. Adapta alergias y preferencias; un profesional puede calcular tus necesidades.</p></section><section class="card"><h2>Compra para los dos</h2><p class="muted">Huevos, pollo o pescado, legumbres, tofu o soya, yogur natural, avena, arroz, arepas, papa, verduras variadas, fruta, aceite y frutos secos.</p><p class="small">Elijan las mismas preparaciones y ajusten las cantidades de cada plato. No hace falta cocinar dos menús distintos para tener dos objetivos diferentes.</p></section></div><section class="card"><div class="section-head"><div><h2>¿Proteína, creatina o vitaminas?</h2><p class="small">Los suplementos son opcionales. Primero van la comida, el entrenamiento y el descanso.</p></div></div><div class="grid3"><article class="supplement"><span class="pill">SOLO SI HACE FALTA</span><h3>Proteína en polvo</h3><p>Puede cubrir lo que falta con la comida. Suero de leche, soya o una mezcla vegetal son opciones; revisa alergias y la cantidad real de proteína por porción. No es obligatorio tomarla al terminar.</p><a href="https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-Consumer/" target="_blank" rel="noopener noreferrer">Proteína · NIH</a></article><article class="supplement"><span class="pill">OPCIONAL</span><h3>Creatina monohidrato</h3><p>En adultos sanos, 3–5 g diarios es una pauta habitual. Puede ayudar a la fuerza y elevar el peso por agua muscular. Consulta antes si hay enfermedad renal, embarazo, medicación o dudas sobre su uso.</p><a href="https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-Consumer/" target="_blank" rel="noopener noreferrer">Creatina · NIH</a></article><article class="supplement"><span class="pill">SEGÚN NECESIDAD</span><h3>Vitaminas y minerales</h3><p>No se eligen por estatura o peso. Hierro y vitamina D requieren evaluar necesidad. Si siguen una dieta vegana, revisen la vitamina B12 con un profesional. Eviten megadosis y productos “quemagrasa”.</p><a href="https://ods.od.nih.gov/factsheets/MVMS-Consumer/" target="_blank" rel="noopener noreferrer">Multivitamínicos · NIH</a></article></div></section><div class="sources"><a href="https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/" target="_blank" rel="noopener noreferrer">Nutrición deportiva · NIH</a><a href="https://www.nhlbi.nih.gov/health/sleep/how-much-sleep" target="_blank" rel="noopener noreferrer">Sueño · NHLBI</a><a href="https://fdc.nal.usda.gov/" target="_blank" rel="noopener noreferrer">Composición de alimentos · USDA</a></div></div>`;
}
function chart(points){
 if(!points.length)return `<div class="empty">${icon('chart')}<p>Todavía no hay medidas. Registra tu punto de partida y vuelve cada semana.</p></div>`;
 const min=Math.min(...points.map(p=>p.v)),max=Math.max(...points.map(p=>p.v)),lo=min-1,hi=max+1;
 const start=points[0].d,end=points.at(-1).d,days=Math.max(1,diff(end,start));
 const xy=p=>[45+diff(p.d,start)/days*440,160-(p.v-lo)/(hi-lo)*120];
 const line=points.map(p=>xy(p).join(',')).join(' ');
 return `<svg class="chart" viewBox="0 0 530 205" role="img" aria-label="Peso registrado de ${fmt(points[0].v)} a ${fmt(points.at(-1).v)} kilogramos. ${points.length} mediciones.">${[lo,(lo+hi)/2,hi].map(v=>{const y=160-(v-lo)/(hi-lo)*120;return `<line x1="45" y1="${y}" x2="495" y2="${y}" stroke="#e4e9dc"/><text x="4" y="${y+4}">${fmt(v)}</text>`;}).join('')}<polyline points="${line}" fill="none" stroke="#618546" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points.map(p=>{const [x,y]=xy(p);return `<circle cx="${x}" cy="${y}" r="4.5" fill="#193e32"><title>${prettyDate(p.d)}: ${fmt(p.v)} kg</title></circle>`;}).join('')}<text x="45" y="192">${prettyDate(start)}</text>${end!==start?`<text x="485" y="192" text-anchor="end">${prettyDate(end)}</text>`:''}</svg>`;
}
function progressView(){
 const id=data.active,p=data.profiles[id],rows=entriesInRange(data,id,today()),pts=weights(data,id,today()),count=completed(data,id,today()),delta=pts.length>1?pts.at(-1).v-pts[0].v:null,recent=rows.filter(([d])=>diff(today(),d)<=6);
 return header('Mira todo lo que sumas.','Cada registro cuenta. Compara tus hábitos y tu rendimiento contigo, sin competir con el otro perfil.')+`<div class="stack"><div class="grid2"><section class="card"><div class="section-head"><h2>Peso de ${esc(p.name)}</h2><button class="btn" data-action="daily">${icon('plus')} Medida</button></div><div class="metric-pair"><div><b>${pts.length?fmt(pts.at(-1).v):'—'} <small>kg</small></b><small>Último valor</small></div><div><b>${delta===null?'—':(delta>0?'+':'')+fmt(delta)} <small>kg</small></b><small>Cambio registrado</small></div></div>${chart(pts)}<p class="small">Usa condiciones parecidas: mañana, después de ir al baño y antes de desayunar. El peso fluctúa; un cambio no demuestra pérdida de grasa o ganancia muscular.</p></section><section class="card"><div class="section-head"><h2>Tus hábitos recientes</h2><span class="pill">7 DÍAS</span></div><div class="list">${[['Proteína',average(recent,'protein'),'g/día','food'],['Sueño',average(recent,'sleep'),'h/noche','moon'],['Energía',average(recent,'energy'),'/10','heart'],['Actividad registrada',recent.length?recent.reduce((a,[,r])=>a+(r.minutes||0),0):null,'min anotados','clock']].map(([label,v,unit,ico])=>`<div class="list-row">${icon(ico)}<div class="row between full"><span>${label}</span><b>${fmt(v)} <span class="small">${unit}</span></b></div></div>`).join('')}</div><p class="small">Los promedios usan solo días con ese dato. Un espacio vacío no cuenta como cero.</p><hr class="subtle-divider">${hints()}</section></div><section class="card"><h2>Dos personas, dos recorridos</h2><div class="table-scroll"><table><thead><tr><th>Perfil</th><th>Inicio</th><th>Último peso</th><th>Fuerza completada</th><th>Observación propia</th></tr></thead><tbody>${IDS.map(pid=>{const w=weights(data,pid,today()),n=completed(data,pid,today());return `<tr><td><b>${esc(data.profiles[pid].name)}</b></td><td>${data.profiles[pid].weight?fmt(data.profiles[pid].weight)+' kg':'—'}</td><td>${w.length?fmt(w.at(-1).v)+' kg':'—'}</td><td>${n} / 12</td><td>${n<3?'Consolidar el hábito':'Revisar técnica y recuperación'}</td></tr>`;}).join('')}</tbody></table></div><p class="small">Las diferencias de peso o carga entre los dos no indican quién avanza mejor. Cada persona parte de un punto distinto.</p></section><section class="card"><h2>Historial de entrenamientos</h2>${Object.entries(data.sessions[id]).length?Object.entries(data.sessions[id]).sort(([a],[b])=>b.localeCompare(a)).map(([date,s])=>`<details class="history-detail"><summary><b>${prettyDate(date)} · ${plan(diff(date,data.start)+1).label}</b> · ${s.done?'Completada':'Parcial'}${s.pain?' · Dolor registrado':''}</summary><div class="table-scroll"><table><thead><tr><th>Ejercicio</th><th>Carga</th><th>Resultado</th></tr></thead><tbody>${Object.entries(s.exercises).filter(([,e])=>e.sets>0).map(([mid,e])=>`<tr><td>${MOVES[mid].name}</td><td>${e.load===null?'—':fmt(e.load)+' kg'}</td><td>${e.sets} × ${e.reps} ${MOVES[mid].time?'s':'reps'}${MOVES[mid].side?'/lado':''}</td></tr>`).join('')}</tbody></table></div>${s.notes?`<p>${esc(s.notes)}</p>`:''}<button class="btn flat" data-day="${diff(date,data.start)+1}">Editar sesión</button></details>`).join(''):`<div class="empty">${icon('dumbbell')}<p>Tu primera sesión aparecerá aquí cuando la guardes. No hay entrenamientos de ejemplo mezclados con tus datos.</p></div>`}</section><section class="card"><div class="section-head"><h2>Registro diario</h2><button class="btn" data-action="daily">Añadir día</button></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Día</th><th>Peso</th><th>Cintura</th><th>Proteína</th><th>Sueño</th><th>Energía</th><th></th></tr></thead><tbody>${[...rows].reverse().map(([d,r])=>`<tr><td>${prettyDate(d)}</td><td>${fmt(r.weight)} kg</td><td>${fmt(r.waist)} cm</td><td>${fmt(r.protein)} g</td><td>${fmt(r.sleep)} h</td><td>${fmt(r.energy)} /10</td><td><button class="btn flat" data-action="daily" data-date="${d}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:`<p class="small">Aún no hay registros diarios de este perfil.</p>`}</section></div>`;
}
function settingsView(){
 return header('Tu espacio, tus datos.','Dos perfiles independientes. Puedes ajustar sus nombres, medidas y objetivos.')+`<div class="stack"><section class="card"><h2>Perfiles</h2><form id="settings-form"><div class="grid2">${IDS.map(id=>{const p=data.profiles[id];return `<div><div class="row"><span class="avatar ${id}">${esc(p.name.slice(0,1).toUpperCase())}</span><h3>${esc(p.name)}</h3></div><div class="form-grid"><label class="full">Nombre<input name="${id}-name" value="${esc(p.name)}" maxlength="30" required autocomplete="off"></label><label>Estatura · cm<input name="${id}-height" type="number" inputmode="decimal" min="120" max="230" step="0.1" value="${p.height??''}" placeholder="Tu estatura"></label><label>Peso inicial · kg<input name="${id}-weight" type="number" inputmode="decimal" min="25" max="300" step="0.1" value="${p.weight??''}" placeholder="Tu punto de partida"></label><label class="full">Objetivo<select name="${id}-goal">${Object.entries(GOALS).map(([k,v])=>`<option value="${k}" ${p.goal===k?'selected':''}>${v}</option>`).join('')}</select></label></div></div>`;}).join('')}</div><hr class="subtle-divider"><div class="form-grid"><label>Fecha de inicio compartida<input type="date" name="start" value="${data.start}" required></label><p class="small">El peso inicial es tu punto de partida y se usa para la referencia de proteína. Las medidas nuevas se anotan en “Registrar día”. Cambiar la fecha con registros existentes requiere comenzar un plan nuevo.</p></div><div class="form-actions"><button type="submit" class="btn primary">${icon('save')} Guardar perfiles</button></div></form></section><div class="grid2"><section class="card"><h2>Tu copia de seguridad</h2><p class="muted">El progreso vive en este navegador. No se sincroniza entre celulares. Exporta una copia antes de cambiar de dispositivo o borrar datos.</p><p class="small">Si comparten este navegador, ambos perfiles están disponibles para quien lo use. El archivo de respaldo contiene los datos de los dos: guárdalo en un lugar personal.</p><div class="form-actions"><button class="btn primary" data-action="export">${icon('download')} Exportar copia</button><button class="btn" data-action="import">Importar copia</button></div><input class="hidden" type="file" id="import-file" accept=".json,application/json"></section><section class="card"><h2>Úsala como aplicación</h2><p class="muted">Abre la dirección publicada en Safari o Chrome. En el menú del navegador, elige “Añadir a pantalla de inicio” o “Instalar aplicación”.</p><p class="small">No requiere crear una cuenta. Una vez cargados todos sus archivos en una dirección HTTPS, puede consultarse sin conexión en navegadores compatibles.</p><div class="form-actions"><button class="btn" data-action="install">${icon('plus')} Añadir a mi celular</button></div><p id="offline-status" class="small">${'serviceWorker' in navigator?'Comprobando disponibilidad sin conexión…':'Tu navegador puede usar la página; el modo sin conexión no está disponible.'}</p></section></div><section class="card"><h2>Comenzar otro mes</h2><p class="muted">Crea una copia antes de empezar. Esta acción conserva los perfiles y vacía los registros del plan en este navegador.</p><div class="form-actions"><button class="btn danger" data-action="new-plan">Preparar un nuevo mes</button></div></section><section class="card"><h2>Sobre este primer plan</h2><p>La base permite entrenar juntos, pero los pesos de las máquinas, el esfuerzo y el avance se deciden por persona. No se asignan cargas por sexo, talla o peso corporal.</p><p class="small">Este plan general para adultos no sustituye la evaluación individual de un entrenador o profesional de salud. No tenemos edad, experiencia, lesiones ni restricciones alimentarias. Ante una limitación, adapta el plan antes de seguirlo.</p></section></div>`;
}
function openDaily(date=today()){
 if(!validDate(date)||date>today())return;
 const dialog=document.getElementById('daily-dialog');fillDaily(dialog,date);dialog.showModal();
}
function fillDaily(dialog,date){
 const r=data.logs[data.active][date]||{};
 dialog.innerHTML=`<h2>Registra tu día</h2><p class="muted">${esc(data.profiles[data.active].name)} · Los campos son opcionales; anota solo lo que conoces.</p><form id="daily-form"><label>Fecha<input type="date" id="daily-date" name="date" max="${today()}" value="${date}" required></label><div class="form-grid">${[['weight','Peso · kg','0.1','Ej. tu medida de hoy'],['waist','Cintura · cm','0.1','Una vez por semana'],['protein','Proteína · g','1','Total de tus comidas'],['sleep','Sueño · horas','0.5','Cuánto dormiste'],['water','Agua · litros','0.1','Agua que tomaste'],['energy','Energía · 1 a 10','1','Cómo te sentiste'],['minutes','Actividad · minutos','1','Caminata, bici o similar']].map(([key,label,step,ph])=>`<label>${label}<input name="${key}" type="number" inputmode="decimal" min="${FIELDS[key][0]}" max="${FIELDS[key][1]}" step="${step}" placeholder="${ph}" value="${r[key]??''}"></label>`).join('')}<label class="full">Notas<textarea name="notes" maxlength="1000" placeholder="Qué salió bien y qué quisieras ajustar…">${esc(r.notes||'')}</textarea></label></div><p class="small">Cintura: mide horizontalmente en el mismo punto, tras una exhalación normal, sin apretar la cinta.</p><div class="form-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn primary" type="submit">Guardar día</button></div></form>`;
 dialog.querySelector('#daily-date').addEventListener('change',e=>{if(!validDate(e.target.value)||e.target.value>today())return;if(dirty&&!confirm('¿Cambiar de fecha y descartar los campos sin guardar?')){e.target.value=date;return;}dirty=false;fillDaily(dialog,e.target.value);});
}
function downloadBackup(raw=null){
 const a=document.createElement('a'),blob=new Blob([raw||JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);a.href=url;a.download='duo-gym-copia-'+today()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function bindImport(){
 document.getElementById('import-file').addEventListener('change',async e=>{
  const file=e.target.files[0];if(!file)return;
  if(file.size>2*1024*1024){toast('La copia es demasiado grande. Máximo: 2 MB.');e.target.value='';return;}
  try{const next=cleanData(JSON.parse(await file.text()));if(!confirm('Esta copia reemplazará los perfiles y registros de este navegador. ¿Ya guardaste una copia y quieres continuar?'))return;
   const wasBlocked=storageBlocked;storageBlocked=false;
   if(persist(next,'Copia importada correctamente.')){storageWarning='';selectedDay=Math.min(30,Math.max(1,diff(today(),data.start)+1));render();}else storageBlocked=wasBlocked;
  }catch(error){toast(error.message||'No se pudo importar la copia.');}finally{const input=document.getElementById('import-file');if(input)input.value='';}
 });
 if('serviceWorker'in navigator)navigator.serviceWorker.ready.then(()=>{const e=document.getElementById('offline-status');if(e)e.textContent='Archivos listos para volver a consultar esta aplicación sin conexión.';});
}
root.addEventListener('input',e=>{if(e.target.closest('form')&&e.target.id!=='daily-date')dirty=true;});
root.addEventListener('click',async e=>{
 const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.profile){if(!abandon())return;const next=clone();next.active=btn.dataset.profile;if(persist(next))render();return;}
 if(btn.dataset.view){if(!abandon())return;view=btn.dataset.view;dirty=false;render();window.scrollTo({top:0});return;}
 if(btn.dataset.day){if(!abandon())return;selectedDay=Number(btn.dataset.day);view='workout';dirty=false;render();return;}
 if(btn.dataset.menu){menuDay=Number(btn.dataset.menu);render();return;}
 const action=btn.dataset.action;
 if(action==='today'){if(!abandon())return;selectedDay=Math.min(30,Math.max(1,diff(today(),data.start)+1));view='workout';dirty=false;render();window.scrollTo({top:0});}
 if(action==='daily'){if(!abandon())return;dirty=false;openDaily(btn.dataset.date||today());}
 if(action==='close-dialog'){if(!abandon())return;dirty=false;document.getElementById('daily-dialog').close();}
 if(action==='export')downloadBackup(storageBlocked&&storedRaw?storedRaw:null);
 if(action==='import')document.getElementById('import-file').click();
 if(action==='install'){if(installEvent){await installEvent.prompt();installEvent=null;}else toast('En Safari: Compartir → Añadir a pantalla de inicio. En Chrome: menú ⋮ → Añadir a pantalla de inicio.');}
 if(action==='new-plan'){
  if(!confirm('Se conservarán los perfiles y se borrarán los registros actuales de ambos. Exporta una copia primero. ¿Continuar?'))return;
  const next=fresh();next.profiles=clone().profiles;next.active=data.active;
  storageBlocked=false;if(persist(next,'Nuevo mes preparado.')){storageWarning='';storedRaw=null;selectedDay=1;render();}
 }
});
root.addEventListener('submit',e=>{
 e.preventDefault();const form=e.target,fd=new FormData(form);
 try{
  const next=clone();
  if(form.id==='settings-form'){
   for(const id of IDS){next.profiles[id]={name:String(fd.get(id+'-name')).trim().slice(0,30)||data.profiles[id].name,height:numberOrNull(fd.get(id+'-height'),120,230),weight:numberOrNull(fd.get(id+'-weight'),25,300),goal:fd.get(id+'-goal')};}
   const start=fd.get('start');if(!validDate(start))throw Error('Elige una fecha de inicio válida.');
   if(start!==data.start&&IDS.some(id=>Object.keys(data.sessions[id]).length||Object.keys(data.logs[id]).length))throw Error('Para cambiar la fecha con registros guardados, exporta una copia y comienza un nuevo mes.');
   next.start=start;
   if(persist(cleanData(next),'Perfiles guardados.')){selectedDay=Math.min(30,Math.max(1,diff(today(),data.start)+1));render();}
  }
  if(form.id==='daily-form'){
   const date=fd.get('date');if(!validDate(date)||date>today())throw Error('Elige hoy o una fecha anterior.');
   if(date<data.start)throw Error('Elige una fecha desde el inicio del plan.');
   const row={};for(const [k,r]of Object.entries(FIELDS))row[k]=numberOrNull(fd.get(k),...r);
   row.notes=String(fd.get('notes')||'').trim().slice(0,1000);
   if(!Object.values(row).some(v=>v!==null&&v!==''))throw Error('Añade al menos un dato o una nota.');
   next.logs[data.active][date]=row;if(persist(cleanData(next),'Día guardado para '+data.profiles[data.active].name+'.'))render();
  }
  if(form.id==='session-form'){
   const date=form.dataset.date;if(date>today())throw Error('No se pueden completar sesiones futuras.');
   const pl=plan(diff(date,data.start)+1),row={done:fd.has('done'),pain:fd.has('pain'),notes:String(fd.get('notes')||'').trim().slice(0,1000),exercises:{}};
   for(const id of ROUTINES[pl.routine]){const sets=numberOrNull(fd.get(id+'-sets'),0,10),reps=numberOrNull(fd.get(id+'-reps'),1,180),load=numberOrNull(fd.get(id+'-load'),0,500);if(sets!==null||reps!==null||load!==null)row.exercises[id]={sets:sets||0,reps,load};}
   if(!Object.keys(row.exercises).length&&!row.notes&&!row.pain)throw Error('Anota al menos un ejercicio, una nota o una molestia.');
   next.sessions[data.active][date]=row;
   if(persist(cleanData(next),'Sesión guardada para '+data.profiles[data.active].name+'.'))render();
  }
 }catch(error){toast(error.message||'Revisa los datos antes de guardar.');}
});
root.addEventListener('cancel',e=>{if(e.target.tagName==='DIALOG'&&dirty&&!confirm('¿Cerrar sin guardar este día?'))e.preventDefault();else dirty=false;},true);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('storage',e=>{
 if(e.key!==KEY||!e.newValue)return;
 if(dirty){storageBlocked=true;storageWarning='Otra pestaña cambió los datos. El guardado está detenido para evitar sobrescribirlos. Revisa tus campos y recarga para usar la versión más reciente.';toast(storageWarning);return;}
 try{data=cleanData(JSON.parse(e.newValue));render();toast('Datos actualizados desde otra pestaña.');}catch{toast('No se pudo leer el cambio de otra pestaña.');}
});
render();
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{const e=document.getElementById('offline-status');if(e)e.textContent='Usa conexión a internet; este navegador no pudo preparar el modo sin conexión.';});
})();
